mapper.select:
select * from ( SELECT ETR_ENTRUST_ADD.SETTLE_SPREED settleSpeed, ETR_ENTRUST.ENTRUST_STATUS entrustStatus, ETR_ENTRUST.ENTRUST_DATE createTimeVal, ETR_ENTRUST.PORTFOLIO_ID portfolioId, ETR_ENTRUST.ENTRUST_ID entrustId, ETR_ENTRUST_ADD.ASSET_TYPE finprodType2, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, ETR_ENTRUST.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_ABBR finprodAbbr, ETR_ENTRUST.PS ps, ETR_ENTRUST_ADD.BUSI_PS busiPs, ETR_ENTRUST.TRADE_MARKET tradeMarket,
ETR_ENTRUST.TRADE_PLAT tradePlat,
ETR_ENTRUST.CHL_ID chlId, ETR_ENTRUST_ADD.SEC_ACCT_ID secAcctId,
ETR_ENTRUST_ADD.TERM_TYPE termType,
ETR_ENTRUST_ADD.ASSET_TYPE1 assetType1, decode(ETR_ENTRUST_ADD.ASSET_TYPE,'F01',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0),'F10',NVL(ETR_ENTRUST.ENTRUST_NUM * 100,0), NVL(ETR_ENTRUST.ENTRUST_AMT,ETR_ENTRUST.ENTRUST_NUM))- NVL(match.match_num,0) proAvailableCash, ETR_ENTRUST.CCY ccy, ETR_DISTRIBUTE.TRADER trader, ETR_ENTRUST.REMARK remark, ETR_ENTRUST.VDATE vdate, ETR_ENTRUST.MDATE mdate, ETR_ENTRUST_ADD.TERM_DAYS repoTerm, ETR_ENTRUST.price price, ETR_ENTRUST_ADD.MATURE_YIELD matureYield, ETR_ENTRUST_ADD.EXER_YIELD exerYield, ETR_ENTRUST.PRICE_MODEL priceMode ,nvl(capacct.busi_acct_no, ( SELECT ptlacct.busi_acct_no FROM ptl_sec_acct plt LEFT JOIN STL_SEC_ACCT_INFO ptlsec ON ptlsec.sec_acct_id=plt.acct_no LEFT JOIN stl_capacct_info ptlacct ON ptlacct.acct_no =ptlsec.trd_acct_id WHERE ptlacct.busi_acct_no =#{ourdepositaccountnumber} AND plt.portfolio_id =ETR_ENTRUST.portfolio_id and rownum=1 )) busi_acct_no FROM ETR_DISTRIBUTE INNER JOIN ETR_ENTRUST ON ETR_DISTRIBUTE.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN FIN_PRODUCT ON FIN_PRODUCT.FINPROD_ID = ETR_ENTRUST.FINPROD_ID INNER JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN STL_SEC_ACCT_INFO secstl ON secstl.sec_acct_id=ETR_ENTRUST_ADD.SEC_ACCT_ID LEFT JOIN stl_capacct_info capacct ON capacct.acct_no =secstl.trd_acct_id LEFT JOIN (select m.entrust_id,sum(m.match_num) match_num from TRD_MATCH_INFO m group by m.entrust_id) MATCH on match.entrust_id=ETR_ENTRUST.ENTRUST_ID Left join sys_user u on u.user_name=ETR_DISTRIBUTE.TRADER
ETR_ENTRUST.ENTRUST_STATUS IN(#{entrustCompleted},#{entrustReceive},#{entrustClose}) AND ETR_DISTRIBUTE.REC_STATUS IN(#{entrustCompleted},#{entrustReceive},#{entrustClose})
AND ETR_ENTRUST_ADD.ASSET_TYPE = #{finprodType2,jdbcType=VARCHAR}
AND FIN_PRODUCT.FINPROD_MARKET_ID = #{securityID,jdbcType=VARCHAR}
AND ETR_ENTRUST.TRADE_MARKET = #{tradeMarket}
AND ETR_ENTRUST.PS =#{side}
AND ETR_ENTRUST.ENTRUST_STATUS IN (#{entrustStatus1},#{entrustStatus2})
AND ETR_ENTRUST.ENTRUST_STATUS = #{entrustStatus}
AND ETR_ENTRUST_ADD.ASSET_TYPE in ('F01','F07') and ETR_ENTRUST.TRADE_MARKET in ('01','03','04')
and ETR_ENTRUST_ADD.SETTLE_SPREED = #{settleSpeed}
AND ETR_ENTRUST.VDATE >= to_date(#{tradeDate},'yyyy-MM-dd') AND ETR_ENTRUST.MDATE <= to_date(#{tradeDate},'yyyy-MM-dd')
and ETR_ENTRUST_ADD.TERM_DAYS = #{repoTerm}
and u.real_name = #{traderName}
) where proAvailableCash <> 0 and busi_acct_no = #{ourdepositaccountnumber} ORDER BY proAvailableCash DESC,createTimeVal ASC
